// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        vm.deal(address(0x1), 30 ether);

        // Warp to block.timestamp = 100
        vm.warp(100);
        // Make block.number not divisible by 15 so the transfer doesn't affect us
        vm.roll(1);

        vm.prank(address(0x1));
        c.fall{value: 10 ether}();

        // Warp to block.timestamp = 200 (ensuring > 100)
        vm.warp(200);
        // Change block.number to something not divisible by 15
        vm.roll(2);

        vm.prank(address(0x1));
        c.fall{value: 10 ether}();

        // Now pastBlockTime for reference = 200, for bug = 199
        // Warp to block.timestamp = 200 again (not > 200 for reference, > 199 for bug)
        vm.warp(200);
        vm.roll(3);

        bool ok;
        vm.prank(address(0x1));
        try c.fall{value: 10 ether}() {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference reverts (pastBlockTime = 200, require fails), bug succeeds
        assertTrue(ok == false);
    }
}

