pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set block.number to 15 (multiple of 15) to trigger transfer
        vm.roll(15);
        // Set block.timestamp to a known value
        vm.warp(1000);

        // Fund the contract with ether
        vm.deal(address(c), 10 ether);

        // First call: set pastBlockTime
        vm.prank(address(0x1));
        c.fall{value: 10 ether}();

        // After first call: pastBlockTime should be 1000 (reference) or 999 (bug)
        // The balance transfer happened, so pastBlockTime was set

        // Call again at a later time, but not a multiple of 15
        vm.warp(2000);
        vm.roll(16);

        // Second call
        vm.prank(address(0x2));
        c.fall{value: 10 ether}();

        // Now check: reference stores 2000, bug stores 1999
        assertTrue(c.pastBlockTime() == 2000);
    }
}

