pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.deal(alice, 30 ether);

        // Warp to block 1, timestamp 1000
        vm.roll(1);
        vm.warp(1000);

        // First fallback call: sets pastBlockTime = 1000 (reference) or 999 (buggy)
        vm.prank(alice);
        c.fall{value: 10 ether}();

        // Warp to block 2, same timestamp 1000
        vm.roll(2);
        vm.warp(1000);

        // Second fallback call: reference succeeds because 1000 > 1000? No, it reverts because block.timestamp == pastBlockTime.
        // Buggy: pastBlockTime was 999, so 1000 > 999 succeeds.
        vm.prank(alice);
        c.fall{value: 10 ether}();

        // Warp to block 3, still timestamp 1000
        vm.roll(3);
        vm.warp(1000);

        bool ok;
        try c.fall{value: 10 ether}() { ok = true; } catch { ok = false; }

        // Reference: third call reverts because pastBlockTime == 1000 (not >). Buggy: pastBlockTime == 999, so 1000 > 999 passes.
        assertTrue(ok);
    }
}

