        vm.warp(1000);

        // First call: succeeds on both reference and bug
        vm.prank(alice);
        c.call{value: 10 ether}('');

        // Second call: same timestamp, should revert on reference (pastBlockTime == 1000), but bug accepts
        bool ok = false;
        vm.prank(alice);
        try c.call{value: 10 ether}('') {
            ok = true;
        } catch {
            ok = false;
        }

        // On the reference, the second call reverts (ok == false); on the bug, it succeeds (ok == true)
        assertTrue(!ok, "Second call should revert on correct contract");
    }
}

