pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        vm.deal(address(this), 100 ether);
        vm.deal(address(c), 0 ether);

        // First call: timestamp 100, block.number = 1 (not multiple of 15)
        vm.warp(100);
        vm.roll(1);
        (bool success1, ) = address(c).call{value: 10 ether}("");
        assertTrue(success1);

        // Second call: timestamp 200, block.number = 2
        vm.warp(200);
        vm.roll(2);
        (bool success2, ) = address(c).call{value: 10 ether}("");
        assertTrue(success2);

        // Third call: timestamp 300, block.number = 15 (multiple of 15)
        vm.warp(300);
        vm.roll(15);
        (bool success3, ) = address(c).call{value: 10 ether}("");
        assertTrue(success3);

        // Fourth call: timestamp 300 again (same as third)
        // Reference: require(block.timestamp > pastBlockTime) => 300 > 300 false => revert
        // Bug: pastBlockTime never updated, still 200 => 300 > 200 true => success
        bool ok;
        try address(c).call{value: 10 ether}("") {
            ok = true;
        } catch {
            ok = false;
        }

        // After fourth call, reference reverts so balance remains 30 ether (from three successful calls minus 30 sent on the third)
        // Bug succeeds and transfers all balance (30 ether) to caller, balance becomes 0
        // But we can check that the reference has non-zero balance and bug has zero
        // Actually both transfer on the third call, so after third both have 0? 
        // Let's re-analyze:
        // - First call: balance += 10 => 10
        // - Second call: balance += 10 => 20
        // - Third call: since block.number%15==0, transfer(address(this).balance) to msg.sender => balance becomes 0, then +10 => 10? 
        //   Actually order: require passes, then pastBlockTime=300, then if block.number%15==0 { payable(msg.sender).transfer(address(this).balance); }
        //   So before transfer balance is 20 (from first two calls), transfer sends 20, then receive 10 from msg.value => balance becomes 10
        // - Fourth call reference reverts, balance stays 10
        // - Fourth call bug succeeds: pastBlockTime never updates, so condition passes, no transfer because block.number=15? Wait, roll(15) only for third call
        //   We didn't roll for fourth call, so block.number remains 15? Actually roll sets block.number for the next call only. After third call, block.number=15. For fourth call, we didn't change block.number, so it's still 15. So fourth call also has block.number%15==0 true, so it transfers the balance (10) to caller, then adds 10 => balance becomes 10 again.
        // Actually we need to set block.number for fourth call to something not multiple of 15 to avoid transfer.
        vm.roll(16); // fourth call at block.number 16 (not multiple of 15)
        bool ok2;
        try address(c).call{value: 10 ether}("") {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        // Now: reference reverted => balance unchanged (10 ether)
        // Bug succeeded => balance increased by 10 => 20 ether (since no transfer because block.number%15!=0)
        assertTrue(address(c).balance == 10 ether || address(c).balance == 20 ether);
        // Actually we need an assertion that reference holds and bug breaks.
        // Reference: ok2 == false (revert), bug: ok2 == true (success)
        // We'll assert that the call reverts (reference behavior). Bug will pass this assertion? No, bug's ok2 is true, so assertion fails.
        assertTrue(!ok2); // reference: revert => ok2 false => !ok2 true; bug: success => ok2 true => !ok2 false
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Send 1 ether (not 10 ether) to trigger the divergence
        // Reference: require(msg.value == 10 ether) fails, pastBlockTime unchanged
        // Mutant:   require(msg.value != 10 ether) passes, pastBlockTime updated
        uint initialPastBlockTime = c.pastBlockTime();
        vm.deal(address(this), 1 ether);
        (bool success, ) = address(c).call{value: 1 ether}("");
        assertTrue(success);
        uint finalPastBlockTime = c.pastBlockTime();
        assertTrue(finalPastBlockTime != initialPastBlockTime);
    }
}
